import{_ as l,a0 as n,w as p,s as u,ao as a,I as s,x as e,a1 as r,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"计算机正常运行最大的威胁是什么？是员工 | LCTT x X-CMD","titleTemplate":false,"description":"计算机正常运行最大的威胁是什么？是员工 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"计算机正常运行最大的威胁是什么？是员工 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"计算机正常运行最大的威胁是什么？是员工 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20191010 The biggest risk to uptime- Your staff","title":"计算机正常运行最大的威胁是什么？是员工","tag":"202101","desc":""},"relativePath":"202101/20191010 The biggest risk to uptime- Your staff.md","filePath":"[post].md"}'),f={name:"202101/20191010 The biggest risk to uptime- Your staff.md"};function m(d,t,T,g,w,k){const o=n("Link");return p(),u("div",null,[t[18]||(t[18]=a('<h1 id="计算机正常运行最大的威胁是什么-是员工" tabindex="-1">计算机正常运行最大的威胁是什么？是员工 <a class="header-anchor" href="#计算机正常运行最大的威胁是什么-是员工" aria-label="Permalink to “计算机正常运行最大的威胁是什么？是员工”">​</a></h1><blockquote><p>一项新研究发现，人为失误是引发停机时间的首要原因。你想象一下那是什么场景。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/07/9_how-well-do-you-know-your-staff_head-in-sand-100765388-large.jpg" alt=""></p><p>之前有一个很老的笑话：“是人都会犯错，但是要真正把事情搞砸，你还缺台计算机。” 现在情况正好相反了，现如今，数据中心设备的可靠性已经得到了极大的提升，反而是使用设备的人员素质没能跟上，从而给计算机正常运行带来了很大的威胁。</p><p><ruby>正常运行时间协会<rt>Uptime Institute</rt></ruby>对数千名 IT 专业人员一整年发生的故障事件进行了调查，得出结论表示绝大多数的数据中心故障是由于人为错误造成的，人为错误导致的故障率为 70%-75%。</p><p>而且有些故障很严重。调查发现，超过 30% 的 IT 服务与数据中心运营商经历了他们称之为是“严重服务退化”的停机事故。2019 年有 10% 的受访者称他们最近的事故造成的损失超过 100 万美元。</p><p>在正常运行时间协会在 2019 年 4 月的调查中，60% 的受访者认为，对于最近发生的重大停机事件，他们本可以通过更好的管理/流程或配置进行防止。而对于损失超过 100 万美元的故障事件，这一数字跃升至 74%。</p><p>正常运行时间协会认为，导致故障事件发生的最终的错误不一定是员工，而是令人失望的管理。</p>',8)),s("p",null,[t[1]||(t[1]=e("“这个行业仍然严重依赖于人工去完成一些最基础和最重要的工作，易受人为错误的影响，这一点无法避免，也许可做的防错/防灾措施很有限。”正常运行时间协会期刊的主编 Kevin Heslin 在一篇",-1)),r(o,{href:"https://journal.uptimeinstitute.com/how-to-avoid-outages-try-harder/"},{default:i(()=>[...t[0]||(t[0]=[e("博客文章",-1)])]),_:1}),t[2]||(t[2]=e("中写道。",-1))]),t[19]||(t[19]=s("p",null,"“然而，对这些故障问题的快速调查发现，故障持续存在的主要原因不是人为失误，而是由于管理失误导致，如针对员工培训投资不足，相关政策执行不力，管理程序老旧，低估一名合格员工的重要性，这一系列的管理问题导致了故障停机。” Heslin 继续写道。",-1)),t[20]||(t[20]=s("p",null,"正常运行时间协会指出，公司的 IT 基础设施越复杂，特别是分布式特性基础设施，可能会越容易增加简单的错误层出不穷而导致业务中断的风险。同时指出公司需要意识到基础设施越复杂所涉及的风险就越大。",-1)),t[21]||(t[21]=s("p",null,"并警告说，在人员配备方面，不要以超过公司吸引和应用资源来管理基础设施的速度扩大关键 IT 能力，并在影响关键任务操作之前意识到任何人员和技能短缺。",-1)),t[22]||(t[22]=s("hr",null,null,-1)),s("p",null,[t[4]||(t[4]=e("via: ",-1)),r(o,{href:"https://www.networkworld.com/article/3444762/the-biggest-risk-to-uptime-your-staff.html"},{default:i(()=>[...t[3]||(t[3]=[e("https://www.networkworld.com/article/3444762/the-biggest-risk-to-uptime-your-staff.html",-1)])]),_:1})]),s("p",null,[t[9]||(t[9]=e("作者：",-1)),r(o,{href:"https://www.networkworld.com/author/Andy-Patrizio/"},{default:i(()=>[...t[5]||(t[5]=[e("Andy Patrizio",-1)])]),_:1}),t[10]||(t[10]=e(" 选题：",-1)),r(o,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[6]||(t[6]=[e("lujun9972",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),r(o,{href:"https://github.com/sthwhl"},{default:i(()=>[...t[7]||(t[7]=[e("sthwhl",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创编译，",-1)),r(o,{href:"https://linux.cn/"},{default:i(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const y=l(f,[["render",m]]);export{x as __pageData,y as default};
